let sceneStarted=false;const sceneTimers=[];
function startKrishnaOpening(){if(sceneStarted)return;sceneStarted=true;document.body.style.overflow='hidden';const scene=document.createElement('div');scene.className='krishna-opening';scene.setAttribute('role','dialog');scene.setAttribute('aria-modal','true');scene.setAttribute('aria-label','Light the diyas to celebrate Dhiraj and Neha');const positions=[[50,84,85],[12,88,68],[28,82,62],[72,82,62],[88,88,68],[18,73,53],[82,73,53],[26,65,44],[74,65,44],[32,58,35],[68,58,35],[36,52,28],[64,52,28]];scene.innerHTML='<div class="opening-garden"></div><div class="opening-sky"></div><div class="opening-caption">जय श्री कृष्णा<br><span style="font:11px DM Sans,sans-serif;letter-spacing:3px">A CELEBRATION OF LOVE</span></div><div class="diya-trail">'+positions.map(([x,y,s],i)=>`<div class="scene-diya ${i===0?'lit':''}" style="left:${x}%;top:${y}%;--lamp-size:${s}px"><img src="diya-lamp.svg" alt=""></div>`).join('')+'</div>'+[[25,20,240,0],[73,15,260,.6],[48,28,210,1.1],[15,35,180,1.7],[85,34,200,2.1]].map(([x,y,s,d])=>`<div class="opening-firework" style="left:${x}%;top:${y}%;--burst-size:${s}px;--burst-delay:${d}s"><img src="golden-firework.svg" alt=""></div>`).join('')+'<button class="light-diyas">Tap to light the diyas ✨</button><div class="opening-names"><p>WITH KRISHNA’S BLESSINGS</p><h2>Dhiraj & Neha</h2><button class="opening-continue">Read the invitation ↓</button></div><button class="opening-skip">Skip opening →</button><div class="scene-status" role="status" style="position:absolute;width:1px;height:1px;overflow:hidden"></div>';document.body.append(scene);let lighting=false;const finish=()=>{sceneTimers.forEach(clearTimeout);scene.classList.add('finished');document.body.style.overflow='';document.querySelector('.hero h1').focus({preventScroll:true});setTimeout(()=>scene.remove(),1200)};scene.querySelector('.opening-skip').onclick=finish;scene.querySelector('.opening-continue').onclick=finish;scene.addEventListener('keydown',e=>{if(e.key==='Escape')finish();if(e.key==='Tab'){const buttons=[...scene.querySelectorAll('button')].filter(b=>getComputedStyle(b).pointerEvents!=='none');const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});scene.querySelector('.light-diyas').onclick=()=>{if(lighting)return;lighting=true;scene.classList.add('illuminated');scene.querySelector('.scene-status').textContent='The diyas are lighting up.';scene.querySelectorAll('.scene-diya').forEach((lamp,i)=>sceneTimers.push(setTimeout(()=>lamp.classList.add('lit'),motion?0:i*140)));sceneTimers.push(setTimeout(()=>scene.classList.add('celebrating'),motion?100:2100));sceneTimers.push(setTimeout(()=>{scene.classList.add('revealing');scene.querySelector('.scene-status').textContent='Dhiraj and Neha. Your invitation is ready.';scene.querySelector('.opening-continue').focus()},motion?200:4800))};scene.querySelector('.light-diyas').focus()}
new MutationObserver(()=>{if(gate.classList.contains('open'))startKrishnaOpening()}).observe(gate,{attributes:true,attributeFilter:['class']});
// Keep continuous petals behind the opening, then reveal them with the invitation.
const openingPetalVisibility=new MutationObserver(()=>{const active=!!document.querySelector('.krishna-opening:not(.finished)');document.querySelectorAll('.flower-shower').forEach(el=>el.style.visibility=active?'hidden':'')});openingPetalVisibility.observe(document.body,{childList:true,subtree:false});
